#!/bin/sh
# Writes chemcore/THIRD_PARTY to stdout from Cargo.lock: every crate the wheel is built from, with its licence.
set -eu
cd "$(dirname "$0")/.."
cat <<'HEAD'
# Third-party components of chemcore (the water-chemistry core, server only)
#
# Generated by chemcore/scripts/third_party.sh from Cargo.lock; chemcore/scripts/test.sh fails when it is stale.
# The licence gate is `cargo deny --locked check` (chemcore/deny.toml: permissive licences only). Where a crate
# offers a choice ("MIT OR Apache-2.0") chemcore uses it under a permissive option.
#
# The chemistry itself (chemcore-core) depends on libm only; the rest is the Python binding (PyO3) and what
# builds it. Build tools: the Rust toolchain 1.88.0 (MIT OR Apache-2.0), maturin 1.16.0 (MIT OR Apache-2.0),
# cargo-deny 0.20.2 (MIT OR Apache-2.0), none shipped.

HEAD
cargo tree --locked -p chemcore-py --edges normal,build --prefix none --format '{p}|{l}' \
  | grep -v '^chemcore-' | sed 's/ (.*)|/|/; s/ (\*)$//' | sort -u \
  | awk -F'|' '{ split($1, a, " "); printf "%-28s %-10s %s\n", a[1], a[2], $2 }'
